        score += (open_bins_count as f64 * 10.0) + 50.0;
    }

    // 6. Mean residual balancing: Prefer bins that keep the mean residual stable.
    //    If this bin's post_residual is far from the mean, it increases entropy.
    score += (post_residual as f64 - mean_residual).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Best-Fit logic: Penalize large post_residuals to prioritize tighter fits.
    // We favor smaller post_residuals (the "Best Fit" principle).
    score += post_residual as f64 * 0.5;

    // 2. Lookahead optimization: If the next item fits into the current post_residual,
    // we heavily reward this bin to keep the packing density high.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 1.5;
        // Reward creating a "perfect" bin (residual 0) for the next item
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // 3. New Bin Penalty: Heavily penalize opening a new bin early in the stream.
    // As the stream progresses, the penalty for opening a new bin decreases.
    if bin_residual == bin_capacity {
        score += 45.0 * (1.0 - progress);
        // If there are other bins that could fit this item, penalize opening a new one
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // 4. Global State Balancing: If the current bin is significantly worse than the mean,
    // we penalize it to force the algorithm to consolidate items into better bins.
    if (bin_residual as f64) > mean_residual * 1.2 {
        score += 10.0;
    }

    // 5. Critical Constraint: If this is the last fitting bin, give it a slight preference
    // to prevent unnecessary bin proliferation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalize opening new bins heavily early on, but allow more flexibility as the stream ends.
    // If bin_residual == bin_capacity, this is a new bin candidate.
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: prioritize Best Fit (lower post_residual).
    // We add a penalty for "fragmentation" - leaving small, unusable gaps.
    // Gaps < 10 are generally useless since min item size is 10.
    let mut score = post;
    if post > 0.0 && post < 10.0 {
        score += 50.0;
    }

    // Lookahead logic: if next_item_size is large, avoid leaving small residuals now.
    if next_item_size > 0 {
        let fit_next = post >= next_item_size as f64;
        if !fit_next && post < 20.0 {
            score += 40.0; 
        }
    }

    if is_new_bin {
        // Dynamic threshold for opening new bins. 
        // Penalize the new bin creation based on how many bins are already open 
        // and how much "mean_residual" space is wasted across open bins.
        let penalty = 25.0 + (mean_residual * 0.5) + (open_bins_count as f64 * 2.0);
        score += penalty * (1.0 - (progress * 0.2));
    } else {
        // Reward bins that are already well-utilized.
        // If this bin is the last chance to fit the item (fitting_bins_count == 1), 
        // we strongly prefer it over opening a new one.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Non-linear coupling: favor bins that bring the post-residual closer to the mean_residual
        // to keep bin levels balanced.
        let balance_factor = (post - mean_residual).abs() * 0.1;
        score += balance_factor;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
