        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Perfect fit for lookahead is highly rewarded
                score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
            } else {
                // If the lookahead item cannot fit, penalize residuals that are "near misses"
                // (e.g., leaving 5 space when the next item is 10)
                if post_residual < next_item_size && post_residual > (next_item_size / 2) {
                    score += 10.0;
                }
            }
        }

        // Penalty for creating "dead zones" (residuals < 10, as items are >= 10)
        // These bins become effectively unusable for future items
        if post_residual < 10 {
            score += 40.0;
        }

        // Encourage filling bins to be close to the global mean residual to keep packing uniform
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // 1. Refined Gap Penalty: Exponentially penalize small gaps that are too small to fit common items
    // but large enough to waste space.
    if post_residual > 0 && post_residual < 18 {
        score += 85.0 * (1.2 - (post_residual as f64 / 20.0));
    }

    // 2. Lookahead Synergy: Strengthened reward for future-proofing.
    // If next_item_size is large, favor bins that preserve space for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 110.0 * (1.0 - (slack / 30.0).min(1.0));
        } else if post_residual > 0 {
            // Penalize blocking the next item; aggressive early, easing late.
            score += 65.0 * (1.0 - progress * 0.5);
        }
    }

    // 3. Fitting Bin Pressure: Direct optimization for bin consolidation.
    if fitting_bins_count > 0 && fitting_bins_count <= 2 && bin_residual >= item_size {
        score -= 180.0 / (fitting_bins_count as f64);
    }

    // 4. Dynamic New Bin Thresholding:
    // Tighten the cost of opening new bins by factoring in the ratio of current open bins.
    if bin_residual == bin_capacity {
        score += (mean_residual * 1.5) + (open_bins_count as f64 * 18.0);

        // Late-game hard constraint: aggressive consolidation.
        if progress > 0.65 {
            score += 320.0 * (progress - 0.65);
        }
    } else {
        // 5. Residual Entropy Control: Favor bins that maintain a higher residual density
        // to keep the "mean_residual" lower, effectively increasing packing efficiency.
        let dev = (bin_residual as f64 - mean_residual);
        score += if dev > 0.0 { dev * 0.8 } else { dev.abs() * 0.3 };
    }

    // 6. Targeted Filler Class Packing:
    // Focus on the 25-40 range (common mid-sized items) to prevent "orphan" waste.
    if post_residual >= 25 && post_residual <= 40 {
        score -= 55.0 * (1.0 - progress * 0.2);
    }

    // 7. Progression Scaling: Global density pressure.
    score += progress * 45.0;

    // 8. Residual Normalization: Final weight adjustment to favor exact fits.
    // The addition of (post_residual * 0.05) softens the raw residual slightly,
    // allowing the logic above to prioritize the "best fit" over "best residual".
    score + (post_residual as f64 * 0.05)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Dead Space Penalty: If the post_residual is small (e.g., < 10), it is likely to be unusable.
    // We penalize these "sliver" gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 15.0;
    }

    // 2. Open Bin Pressure: Discourage opening new bins unless the fit is excellent.
    // If this is a new bin (bin_residual == bin_capacity), apply a heavy baseline penalty
    // scaled by how many bins are already open to prevent fragmentation.
    if bin_residual == bin_capacity {
        score += 45.0 + (open_bins_count as f64 * 0.5);
    }

    // 3. Lookahead Sensitivity: If we know the next item, penalize placements that
    // make the current bin unable to fit the next item if it's large.
    if next_item_size > 0 && post_residual < next_item_size {
        // If the current bin will be unable to fit the next item, penalize based on 
        // how "tight" the current fit is.
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // 4. Global Efficiency: Reward filling bins closer to the global mean residual
    // to keep bin utilization balanced.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // 5. Urgency: If this is the only bin that can fit the item, prioritize it
    // to avoid unnecessary new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
