    } else {
        // 5. Variance Control: Penalize deviations from the mean_residual
        // to keep bin levels synchronized for future item distributions.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.75;
    }

    // 6. Filler Class Packing: Aggressively target mid-range gaps.
    // Increased weight to capture items that usually trigger new bin creation.
    if post_residual >= 18 && post_residual <= 38 {
        score -= 55.0;
    }

    // 7. Global Density Momentum:
    // Apply a mild bias toward the end of the stream to consolidate remaining items.
    score += progress * 45.0;

    // 8. Residual Normalization: Final dampening of the raw residual to 
    // prevent simple "first-fit" bias from overriding the lookahead logic.
    score + (post_residual as f64 * 0.05)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
