pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // The objective is to minimize the score.
    // 1. Base cost: post_residual (Best Fit approach).
    // 2. Penalty for creating "dead space": small residuals that are unlikely to fit future items.
    // 3. Lookahead bonus: if the next item fits into the post_residual, prioritize this bin.
    // 4. Global pressure: adjust behavior based on stream progress.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Penalize small, unusable residuals (the "fragmentation" trap).
    // If residual is < 10, it's likely dead space.
    let fragmentation_penalty = if post_residual > 0 && post_residual < 10 {
        15.0 / (post_residual as f64 + 1.0)
    } else {
        0.0
    };

    // Lookahead: If next item fits in the post_residual, this is a strong candidate.
    let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size {
        -25.0 * (post_residual as f64 / bin_capacity as f64)
    } else {
        0.0
    };

    // New Bin Penalty: Heavily discourage opening new bins unless the fit is excellent.
    let new_bin_penalty = if is_new_bin {
        // If we are early in the stream, be more conservative.
        // If we have many open bins, be more aggressive about filling existing ones.
        25.0 + (open_bins_count as f64 * 0.5) - (progress * 10.0)
    } else {
        0.0
    };

    // If this is the last chance for the current item (fitting_bins_count == 1), 
    // prioritize it to avoid opening a new bin unnecessarily.
    let urgency_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -40.0
    } else {
        0.0
    };

    // Combine:
    // We want post_residual to be small (Best Fit), but avoid the range (1..10).
    // We want to favor placements that accommodate the next_item_size.
    let mut score = post_residual as f64 
        + fragmentation_penalty 
        + lookahead_bonus 
        + new_bin_penalty 
        + urgency_bonus;

    // Apply global pressure: as we near the end of the stream, favor closing bins.
    if progress > 0.9 {
        score -= (open_bins_count as f64) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
