    let progress = step_index as f64 / total_items as f64;

    // 1. Refined Gap Penalty: Target the 'unusable' zone (1-29).
    // Increased penalty to prevent creating small, non-fillable slivers that kill density.
    if post_residual > 0 && post_residual < 30 {
        score += 105.0 * (1.0 + progress.powf(0.55));
    }

    // 2. Lookahead Synergy: Exponential decay on slack to prioritize exact matches.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Stronger incentive for near-perfect fits to preserve larger gaps elsewhere.
            score -= 135.0 * (1.0 - (slack / 40.0).min(0.95));
        } else if post_residual > 0 {
            // Penalize blocking the next item; prevent premature fragmentation.
            score += 85.0 * (1.25 - progress);
        }
    }

    // 3. Fitting Bin Pressure: Increased weight for forced consolidation.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 260.0;
    }

    // 4. Dynamic New Bin Thresholding:
    // Non-linear penalty based on current capacity utilization.
    if bin_residual == bin_capacity {
        let utilization_penalty = (open_bins_count as f64 * 22.0) + (mean_residual * 2.1);
        score += utilization_penalty;

        // Late-game hard constraint: heavily discourage opening new bins when density is high.
        if progress > 0.55 {
            score += 450.0 * (progress - 0.55).powf(1.4);
        }
    } else {
        // 5. Variance Control: Favor bins that stay near the running mean.
        // Penalty for bins that drift far from the mean, reducing fragmentation.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.95;
    }

    // 6. Filler Class Packing: Target mid-range items (18-45).
    // Adjusted range to capture items that force high fragmentation in the mid-stream.
    if post_residual >= 18 && post_residual <= 45 {
        score -= 75.0 * (1.0 - progress * 0.12);
    }

    // 7. Global Density Momentum:
    // Favor bins that have already been used, reducing the number of active bins.
    // Increased coefficient to compress bin usage earlier in the stream.
    score -= (bin_capacity - bin_residual) as f64 * 0.12;

    // 8. Residual Normalization: Final dampening to allow the heuristic logic to dictate bin selection.
    score + (post_residual as f64 * 0.04)
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

