    // to discourage opening new bins unless current bins are significantly "cluttered".
    if bin_residual == bin_capacity {
        score = mean_residual * 1.5;
        // If there are many open bins, penalize opening a new one further.
        score += (open_bins_count as f64) * 2.0;
    } else {
        // 2. Harmonic Class logic: Reward post_residuals that are multiples of common item sizes (e.g., 20, 25).
        // This keeps the remaining space "useful" for future items.
        let harmonic_penalty = (post_residual % 20) as f64 * 0.5;
        score += harmonic_penalty;

