    }

    // 4. Tightness bias: If this is the only bin that fits the current item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // 5. Progress normalization: As we approach the end of the stream, be more conservative with bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 5.0;

    score
}

