        let utilization_penalty = (open_bins_count as f64 * 22.0) + (mean_residual * 2.1);
        score += utilization_penalty;

        if progress > 0.5 {
            score += 480.0 * (progress - 0.5).powf(1.4);
        }
    } else {
        // 5. Variance Control: Favor bins that stay near the running mean.
        // Penalty for bins that drift far from the mean, reducing fragmentation.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.95;
    }

    // 6. Filler Class Packing: Target mid-range items (18-45).
    // Expanded range to capture more high-fragmentation items.
    if post_residual >= 18 && post_residual <= 45 {
