    // be more aggressive about closing bins (higher penalty for opening new ones).
    let open_bin_penalty = if bin_residual == bin_capacity {
        // Penalty for opening a new bin scales with progress and current open count
        // to encourage packing into existing infrastructure.
        (100.0 * progress) + (open_bins_count as f64 * 5.0)
    } else {
        0.0
    };

    score += open_bin_penalty;

    // If this is the only bin that can fit the item, prioritize it to avoid 
    // fragmenting space in other bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Coupling: If the mean residual is high, we have plenty of open space; 
    // prioritize filling the most empty bins (Best-Fit).
    // If mean residual is low, we are tight; prioritize the tightest fit (First-Fit/Best-Fit).
    score += (mean_residual - post).abs() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
